try {
  const raw = $input.first().json.candidates[0].content.parts[0].text;
  const parsed = JSON.parse(raw.trim());
  return [{ json: { success: true, aiGenerated: true, ...parsed } }];
} catch (e) {
  const orig = $('Prepare AI Prompt').first().json.originalInput;
  return [{ json: {
    success: true,
    aiGenerated: false,
    triagePriority: orig.isUrgent ? "CRITICAL" : "HIGH",
    breakdownCategory: orig.issueType || "BATTERY_JUMPSTART",
    technicianAssignedName: "On-Duty Basement Support Tech",
    estimatedArrivalMinutes: 15,
    requiredToolKit: ["Portable Jumpstarter & Air Compressor Kit"],
    safetyPrecautions: ["Engage parking brake", "Ensure basement lane is clear"],
    estimatedCostInr: 250,
    coveredUnderSubscription: true,
    auditTimestamp: new Date().toISOString()
  } }];
}
